"""Payroll summary from clock exports. Usage: payroll.py INPUT_DIR OUTPUT_FILE"""
import csv
import datetime as dt
import gzip
import io
import json
import math
import os
import re
import sys
from decimal import Decimal
from fractions import Fraction
from zoneinfo import ZoneInfo

UTC = dt.timezone.utc
EPOCH = dt.datetime(1970, 1, 1, tzinfo=UTC)


# ---------------------------------------------------------------- helpers
def read_text(path):
    with open(path, "rb") as f:
        data = f.read()
    if data[:2] == b"\x1f\x8b":
        data = gzip.decompress(data)
    text = data.decode("utf-8-sig")
    return text


def text_lines(path):
    out = []
    for line in read_text(path).split("\n"):
        line = line.rstrip("\r")
        if line.strip() == "":
            continue
        out.append(line)
    return out


def read_csv_rows(path, delimiter=","):
    lines = text_lines(path)
    return list(csv.reader(lines, delimiter=delimiter))


def read_csv_dicts(path):
    rows = read_csv_rows(path)
    if not rows:
        return []
    hdr = [h.strip() for h in rows[0]]
    return [dict(zip(hdr, [c.strip() for c in r])) for r in rows[1:]]


def to_epoch(aware):
    d = aware - EPOCH
    return d.days * 86400 + d.seconds  # microseconds dropped


def local_to_utc(naive, tz, dst=None):
    """Convert naive local wall time to epoch seconds.

    dst: None -> first occurrence for repeated times; True/False -> pick the
    occurrence with/without daylight saving time."""
    cands = []
    for fold in (0, 1):
        a = naive.replace(tzinfo=tz, fold=fold)
        off = a.utcoffset()
        u = (naive - off).replace(tzinfo=UTC)
        back = u.astimezone(tz).replace(tzinfo=None)
        if back == naive:
            cands.append((to_epoch(u), bool(a.dst())))
    uniq = []
    for c in cands:
        if c not in uniq:
            uniq.append(c)
    if not uniq:
        a = naive.replace(tzinfo=tz, fold=0)
        return to_epoch((naive - a.utcoffset()).replace(tzinfo=UTC))
    if len(uniq) == 1 or dst is None:
        return uniq[0][0]
    for c in uniq:
        if c[1] == dst:
            return c[0]
    return uniq[0][0]


def std_offset_seconds(tz):
    a = dt.datetime(2026, 1, 15, tzinfo=tz)
    b = dt.datetime(2026, 7, 15, tzinfo=tz)
    best = None
    for x in (a, b):
        o = x.utcoffset() - (x.dst() or dt.timedelta(0))
        best = o
        if not x.dst():
            break
    return int(best.total_seconds())


def floor_int(v):
    if isinstance(v, str):
        v = Decimal(v.strip())
    elif isinstance(v, float):
        return math.floor(v)
    return int(math.floor(v)) if not isinstance(v, int) else v


def norm_dir(s):
    s = str(s).strip().upper()
    if s in ("IN", "I", "K", "CLOCK_IN"):
        return "IN"
    if s in ("OUT", "O", "G", "CLOCK_OUT"):
        return "OUT"
    return None


# ---------------------------------------------------------------- parsers
# Each parser yields (punch_id:str, employee:str, direction, epoch_seconds)
def parse_abbr_csv(path, tz):
    rows = read_csv_rows(path)
    hdr = None
    for r in rows:
        cells = [c.strip() for c in r]
        if "Badge" in cells and "Punch" in cells and "Record" in cells:
            hdr = {name: i for i, name in enumerate(cells)}
            continue
        if hdr is None:
            continue
        try:
            g = lambda k: cells[hdr[k]]
            badge = g("Badge")
            d = norm_dir(g("Punch"))
            m, dd, yy = g("Date").split("/")
            tm = g("Time").strip().upper()
            mt = re.fullmatch(r"(\d{1,2}):(\d\d):(\d\d)\s*(AM|PM)?", tm)
            if not mt or d is None:
                continue
            h, mi, s, ap = int(mt.group(1)), int(mt.group(2)), int(mt.group(3)), mt.group(4)
            if ap:
                h = h % 12 + (12 if ap == "PM" else 0)
            naive = dt.datetime(int(yy), int(m), int(dd), h, mi, s)
            zone = g("Zone").strip().upper()
            isdst = True if zone.endswith("DT") else (False if zone.endswith("ST") else None)
            ep = local_to_utc(naive, tz, isdst)
            yield g("Record"), badge, d, ep
        except (KeyError, IndexError, ValueError):
            continue


def parse_epoch_jsonl(path, tz):
    schema = 1
    for line in text_lines(path):
        try:
            o = json.loads(line)
        except ValueError:
            continue
        if not isinstance(o, dict):
            continue
        if "schema" in o and not any(k in o for k in ("id", "punch_id")):
            try:
                schema = int(o["schema"])
            except (TypeError, ValueError):
                pass
            continue
        if o.get("heartbeat") is True:
            continue
        try:
            if schema == 2:
                pid, emp, d = o["punch_id"], o["employee"], norm_dir(o["direction"])
                ep = floor_int(Decimal(str(o["epoch_ms"]))) // 1000
            else:
                pid, emp, d = o["id"], o["emp"], norm_dir(o["dir"])
                if "ts" in o:
                    ep = floor_int(Decimal(str(o["ts"])))
                else:
                    ep = floor_int(Decimal(str(o["ts_ms"]))) // 1000
        except (KeyError, ValueError, ArithmeticError):
            continue
        if d is None:
            continue
        yield (str(pid).strip() if not isinstance(pid, int) else str(pid)), str(emp).strip(), d, ep


def parse_offset_csv(path, tz):
    rows = read_csv_rows(path, ";")
    hdr = None
    for r in rows:
        cells = [c.strip() for c in r]
        if "punch_id" in cells and "timestamp" in cells:
            hdr = {name: i for i, name in enumerate(cells)}
            continue
        if hdr is None:
            continue
        try:
            d = norm_dir(cells[hdr["event"]])
            ts = cells[hdr["timestamp"]]
            if ts.endswith("Z"):
                ts = ts[:-1] + "+00:00"
            a = dt.datetime.fromisoformat(ts)
            if a.tzinfo is None or d is None:
                continue
            yield cells[hdr["punch_id"]], cells[hdr["employee"]], d, to_epoch(a.astimezone(UTC))
        except (KeyError, IndexError, ValueError):
            continue


def parse_legacy_fixed(path, tz):
    default = std_offset_seconds(tz)
    off = default
    for line in text_lines(path):
        t = line[0]
        if t == "H":
            off = default
            seg = line[13:18].strip()
            if re.fullmatch(r"[+-]\d{4}", seg):
                sign = -1 if seg[0] == "-" else 1
                off = sign * (int(seg[1:3]) * 3600 + int(seg[3:5]) * 60)
        elif t == "D":
            try:
                pid = line[1:9]
                badge = line[9:15].strip()
                d = norm_dir(line[15])
                ts = line[16:30]
                naive = dt.datetime.strptime(ts, "%Y%m%d%H%M%S")
                if d is None:
                    continue
                ep = to_epoch((naive - dt.timedelta(seconds=off)).replace(tzinfo=UTC))
                yield pid, "E" + badge, d, ep
            except (ValueError, IndexError):
                continue


def parse_de_tsv(path, tz):
    hdr = None
    for line in text_lines(path):
        cells = [c.strip() for c in line.split("\t")]
        if "Ausweis" in cells and "Nr" in cells:
            hdr = {name: i for i, name in enumerate(cells)}
            continue
        if hdr is None:
            continue
        try:
            g = lambda k: cells[hdr[k]]
            d = norm_dir(g("Buchung"))
            dd, mm, yy = g("Datum").split(".")
            hh, mi = g("Uhrzeit").split(":")[:2]
            naive = dt.datetime(int(yy), int(mm), int(dd), int(hh), int(mi))
            z = g("Zeitzone").strip().upper()
            isdst = True if z == "MESZ" else (False if z == "MEZ" else None)
            if d is None:
                continue
            yield g("Nr"), g("Ausweis"), d, local_to_utc(naive, tz, isdst)
        except (KeyError, IndexError, ValueError):
            continue


def parse_local_csv(path, tz):
    rows = read_csv_rows(path)
    hdr = None
    for r in rows:
        cells = [c.strip() for c in r]
        if "employee_id" in cells and "punch_ref" in cells:
            hdr = {name: i for i, name in enumerate(cells)}
            continue
        if hdr is None:
            continue
        try:
            d = norm_dir(cells[hdr["direction"]])
            naive = dt.datetime.strptime(cells[hdr["local_time"]], "%Y-%m-%d %H:%M:%S")
            if d is None:
                continue
            yield cells[hdr["punch_ref"]], cells[hdr["employee_id"]], d, local_to_utc(naive, tz, None)
        except (KeyError, IndexError, ValueError):
            continue


def parse_local_jsonl(path, tz):
    for line in text_lines(path):
        try:
            o = json.loads(line)
            p = o["punch"]
            pid = p["id"]
            d = norm_dir(p["type"])
            naive = dt.datetime.strptime(p["at"].strip(), "%Y-%m-%d %H:%M:%S")
            emp = str(p["badge"]).strip()
        except (ValueError, KeyError, TypeError, AttributeError):
            continue
        if d is None:
            continue
        yield (str(pid) if isinstance(pid, int) else str(pid).strip()), emp, d, local_to_utc(naive, tz, None)


PARSERS = {
    "abbr-csv": parse_abbr_csv,
    "epoch-jsonl": parse_epoch_jsonl,
    "offset-csv": parse_offset_csv,
    "legacy-fixed": parse_legacy_fixed,
    "de-tsv": parse_de_tsv,
    "local-csv": parse_local_csv,
    "local-jsonl": parse_local_jsonl,
}


# ---------------------------------------------------------------- main
def list_files(d):
    out = []
    for root, dirs, files in os.walk(d):
        dirs.sort()
        for f in sorted(files):
            out.append(os.path.join(root, f))
    return out


def round_punch(ep, tz):
    off = int(dt.datetime.fromtimestamp(ep, UTC).astimezone(tz).utcoffset().total_seconds())
    local = ep + off
    r = local % 360
    delta = -r if r < 180 else 360 - r
    return ep + delta


def local_date(ep, tz):
    return dt.datetime.fromtimestamp(ep, UTC).astimezone(tz).date()


def utc_offset(ep, tz):
    return int(dt.datetime.fromtimestamp(ep, UTC).astimezone(tz).utcoffset().total_seconds())


def night_overlap_local(a, b):
    """Seconds of [a,b) (local epoch seconds) inside 22:00-06:00 local."""
    if b <= a:
        return 0
    total = 0
    d0 = a // 86400 - 1
    d1 = b // 86400 + 1
    for d in range(d0, d1 + 1):
        ws = d * 86400 - 2 * 3600
        we = d * 86400 + 6 * 3600
        lo, hi = max(a, ws), min(b, we)
        if hi > lo:
            total += hi - lo
    return total


def night_seconds(ein, eout, tz):
    if eout <= ein:
        return 0
    oi, oo = utc_offset(ein, tz), utc_offset(eout, tz)
    if oi == oo:
        # assume no double transition inside a shift
        return night_overlap_local(ein + oi, eout + oi)
    # find the transition by bisection (second resolution)
    lo, hi = ein, eout  # offset(lo)==oi, offset(hi)!=oi
    while hi - lo > 1:
        mid = (lo + hi) // 2
        if utc_offset(mid, tz) == oi:
            lo = mid
        else:
            hi = mid
    t = hi
    return (night_overlap_local(ein + oi, t + oi)) + night_segment(t, eout, tz)


def night_segment(a, b, tz):
    if b <= a:
        return 0
    o = utc_offset(a, tz)
    if utc_offset(b - 1, tz) == o:
        return night_overlap_local(a + o, b + o)
    lo, hi = a, b - 1
    while hi - lo > 1:
        mid = (lo + hi) // 2
        if utc_offset(mid, tz) == o:
            lo = mid
        else:
            hi = mid
    return night_overlap_local(a + o, hi + o) + night_segment(hi, b, tz)


def main():
    in_dir, out_file = sys.argv[1], sys.argv[2]
    with open(os.path.join(in_dir, "period.json")) as f:
        period = json.load(f)
    pstart = dt.date.fromisoformat(period["start"])
    pend = dt.date.fromisoformat(period["end"])
    cutoff = dt.datetime.fromisoformat(period["corrections_cutoff"].replace("Z", "+00:00"))
    if cutoff.tzinfo is None:
        cutoff = cutoff.replace(tzinfo=UTC)
    cutoff_ep = to_epoch(cutoff.astimezone(UTC))

    sites = {}
    for r in read_csv_dicts(os.path.join(in_dir, "sites.csv")):
        sites[r["site"]] = (ZoneInfo(r["timezone"]), r["format"])
    employees = {}  # id -> home site
    emp_order = []
    for r in read_csv_dicts(os.path.join(in_dir, "employees.csv")):
        if r["employee_id"] not in employees:
            emp_order.append(r["employee_id"])
        employees[r["employee_id"]] = r["home_site"]
    rates = {}
    for r in read_csv_dicts(os.path.join(in_dir, "rates.csv")):
        rates.setdefault(r["employee_id"], []).append(
            (dt.date.fromisoformat(r["effective_from"]), Fraction(Decimal(r["hourly_rate"]))))
    for k in rates:
        rates[k].sort(key=lambda x: x[0])

    # 1. collect punches: (site, id) -> [employee, dir, epoch]
    punches = {}
    for site, (tz, fmt) in sites.items():
        sdir = os.path.join(in_dir, "exports", site)
        if not os.path.isdir(sdir):
            continue
        parser = PARSERS[fmt]
        for path in list_files(sdir):
            for pid, emp, d, ep in parser(path, tz):
                key = (site, pid)
                if key not in punches:
                    punches[key] = [emp, d, ep]
    existed = set(punches)
    voided = set()

    # 2. corrections
    corrs = []
    cdir = os.path.join(in_dir, "corrections")
    if os.path.isdir(cdir):
        for path in list_files(cdir):
            for r in read_csv_dicts(path):
                try:
                    ia = dt.datetime.fromisoformat(r["issued_at"].replace("Z", "+00:00"))
                    if ia.tzinfo is None:
                        ia = ia.replace(tzinfo=UTC)
                    corrs.append((to_epoch(ia.astimezone(UTC)), r["correction_id"], r))
                except (KeyError, ValueError):
                    continue
    corrs.sort(key=lambda x: (x[0], x[1]))
    applied = 0

    def parse_time(s):
        a = dt.datetime.fromisoformat(s.strip().replace("Z", "+00:00"))
        if a.tzinfo is None:
            return None
        return to_epoch(a.astimezone(UTC))

    for iss, cid, r in corrs:
        if iss > cutoff_ep:
            continue
        action = r.get("action", "").strip().lower()
        key = (r.get("site", ""), r.get("punch_id", ""))
        try:
            if action == "void":
                if key in punches and key not in voided:
                    voided.add(key)
                    del punches[key]
                    applied += 1
            elif action == "set":
                if key in punches and key not in voided:
                    ep = parse_time(r.get("time", ""))
                    if ep is not None:
                        punches[key][2] = ep
                        applied += 1
            elif action == "add":
                if key not in existed:
                    d = norm_dir(r.get("type", ""))
                    ep = parse_time(r.get("time", ""))
                    if d is not None and ep is not None and key[0] in sites:
                        punches[key] = [r.get("employee", ""), d, ep]
                        existed.add(key)
                        applied += 1
        except ValueError:
            continue

    # group per employee, discarding unknown badges
    per_emp = {}
    for (site, pid), (emp, d, ep) in punches.items():
        if emp not in employees:
            continue
        per_emp.setdefault(emp, []).append((ep, 0 if d == "OUT" else 1, site, pid, d))

    in_period = lambda day: pstart <= day <= pend
    exc = {"open_shifts": 0, "orphan_outs": 0, "duplicates_dropped": 0}
    result_emps = {}
    for e in emp_order:
        result_emps[e] = None

    for emp in emp_order:
        home_tz = sites[employees[emp]][0]
        plist = sorted(per_emp.get(emp, []), key=lambda p: (p[0], p[1], p[2], p[3]))
        # 3. duplicates
        kept = []
        for p in plist:
            if kept and kept[-1][4] == p[4] and p[0] - kept[-1][0] <= 300:
                rp = round_punch(p[0], sites[p[2]][0])
                if in_period(local_date(rp, home_tz)):
                    exc["duplicates_dropped"] += 1
                continue
            kept.append(p)
        # 4. round
        rounded = [(round_punch(p[0], sites[p[2]][0]), p[4], p[2]) for p in kept]
        # 5. pair
        shifts = []  # (in_r, out_r, site)
        pending = None
        for r in rounded:
            if r[1] == "IN":
                if pending is not None:
                    if in_period(local_date(pending[0], home_tz)):
                        exc["open_shifts"] += 1
                pending = r
            else:
                if pending is not None and r[0] - pending[0] <= 16 * 3600:
                    shifts.append((pending[0], r[0], pending[2]))
                    pending = None
                else:
                    if pending is not None:
                        if in_period(local_date(pending[0], home_tz)):
                            exc["open_shifts"] += 1
                        pending = None
                    if in_period(local_date(r[0], home_tz)):
                        exc["orphan_outs"] += 1
        if pending is not None and in_period(local_date(pending[0], home_tz)):
            exc["open_shifts"] += 1
        # 6/7. minutes
        rows = []
        for i_r, o_r, site in shifts:
            wd = local_date(i_r, home_tz)
            if not in_period(wd):
                continue
            worked = max(0, (o_r - i_r) // 60)
            paid = worked - 30 if worked > 360 else worked
            night = min(night_seconds(i_r, o_r, sites[site][0]) // 60, paid)
            rows.append({"in": i_r, "wd": wd, "paid": paid, "night": night})
        rows.sort(key=lambda r: r["in"])
        # 8. overtime
        day_used = {}
        for r in rows:
            used = day_used.get(r["wd"], 0)
            reg_before = max(0, min(480, used + r["paid"]) - min(480, used))
            r["daily_ot"] = r["paid"] - reg_before
            day_used[r["wd"]] = used + r["paid"]
        week_used = {}
        for r in rows:
            wk = r["wd"] - dt.timedelta(days=r["wd"].weekday())
            nd = r["paid"] - r["daily_ot"]
            used = week_used.get(wk, 0)
            reg = max(0, min(2400, used + nd) - min(2400, used))
            r["weekly_ot"] = nd - reg
            week_used[wk] = used + nd
        total = Fraction(0)
        paid_sum = ot_sum = night_sum = 0
        for r in rows:
            ot = r["daily_ot"] + r["weekly_ot"]
            reg = r["paid"] - ot
            rate = Fraction(0)
            for eff, val in rates.get(emp, []):
                if eff <= r["wd"]:
                    rate = val
            total += rate * (reg + Fraction(3, 2) * ot) / 60 + rate * Fraction(15, 100) * r["night"] / 60
            paid_sum += r["paid"]
            ot_sum += ot
            night_sum += r["night"]
        cents = math.floor(total * 100 + Fraction(1, 2))
        result_emps[emp] = {
            "shifts": len(rows),
            "paid_minutes": paid_sum,
            "overtime_minutes": ot_sum,
            "night_minutes": night_sum,
            "cents": cents,
        }

    totals = {"shifts": 0, "paid_minutes": 0, "overtime_minutes": 0, "night_minutes": 0}
    tcents = 0
    out_emps = {}
    for e, v in result_emps.items():
        for k in totals:
            totals[k] += v[k]
        tcents += v["cents"]
        out_emps[e] = {k: v[k] for k in totals}
        out_emps[e]["gross"] = "%d.%02d" % divmod(v["cents"], 100)
    totals["gross"] = "%d.%02d" % divmod(tcents, 100)
    exc["corrections_applied"] = applied
    out = {
        "period": {"start": period["start"], "end": period["end"]},
        "employees": out_emps,
        "exceptions": exc,
        "totals": totals,
    }
    d = os.path.dirname(os.path.abspath(out_file))
    os.makedirs(d, exist_ok=True)
    with open(out_file, "w") as f:
        json.dump(out, f, indent=1)


if __name__ == "__main__":
    main()
